using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using AcxiomCRM.ViewModels;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Mvc.Rendering;
namespace AcxiomCRM.Controllers;
public class ActivitiesController(CrmDb db,CrmService crm,AuditService audit):Controller {
public async Task<IActionResult> Index(string? q,string? status,string? owner,int page=1){var rows=crm.Scope<Activity>();if(!string.IsNullOrWhiteSpace(q))rows=rows.Where(x=>x.ActivityType.Contains(q)||x.Subject.Contains(q)||x.Status.Contains(q));if(!string.IsNullOrEmpty(status))rows=rows.Where(x=>x.Status==status);if(!string.IsNullOrEmpty(owner))rows=rows.Where(x=>x.AssignedTo==owner);page=Math.Clamp(page,1,100000);ViewBag.Page=page;ViewBag.Total=await rows.CountAsync();ViewBag.Q=q;ViewBag.Status=status;ViewBag.Owner=owner;await Options();return View(await rows.OrderByDescending(x=>x.Id).Skip((page-1)*15).Take(15).ToListAsync());}
async Task Options(){ViewBag.Owners=new SelectList(await crm.Owners().OrderBy(x=>x.FullName).ToListAsync(),"Id","FullName");ViewBag.Customers=new SelectList(await crm.Scope<Customer>().ToListAsync(),"Id","CustomerName");ViewBag.Leads=new SelectList(await crm.Scope<Lead>().ToListAsync(),"Id","LeadName");}
public async Task<IActionResult> Details(int id){var e=await crm.Scope<Activity>().FirstOrDefaultAsync(x=>x.Id==id);return e==null?NotFound():View(e);}
public async Task<IActionResult> Create(){await Options();ViewBag.Editing=false;return View("Edit",new ActivityInput{AssignedTo=crm.Id});}
public async Task<IActionResult> Edit(int id){var e=await crm.Scope<Activity>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();await Options();ViewBag.Editing=true;ViewBag.Id=id;return View(ActivityInput.From(e));}
[HttpPost] public Task<IActionResult> Create(ActivityInput input)=>Save(null,input);
[HttpPost] public Task<IActionResult> Edit(int id,ActivityInput input)=>Save(id,input);
async Task<IActionResult> Save(int? id,ActivityInput input){var e=id==null?new Activity():await crm.Scope<Activity>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();var before=id==null?null:ActivityInput.From(e);string? oldStatus=null;input.Apply(e);e.AssignedTo=input.AssignedTo??(id==null?crm.Id:e.AssignedTo);if(ModelState.IsValid){var error=await crm.Validate(e,id==null?null:oldStatus);if(error!=null)ModelState.AddModelError("",error);}
if(ModelState.IsValid){await using var tx=await db.Database.BeginTransactionAsync();try{if(id==null)db.Add(e);await db.SaveChangesAsync();audit.Add(id==null?"Create":"Update","Activity",e.Id.ToString(),before,ActivityInput.From(e));await db.SaveChangesAsync();await tx.CommitAsync();TempData["Message"]="Record saved.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){await tx.RollbackAsync();ModelState.AddModelError("","Could not save: duplicate or invalid related record.");}}
await Options();ViewBag.Editing=id!=null;ViewBag.Id=id;return View("Edit",input);}
[HttpPost] public async Task<IActionResult> Delete(int id){var e=await crm.Scope<Activity>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();e.IsDeleted=true;audit.Add("Delete","Activity",id.ToString(),ActivityInput.From(e));await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
}
